// План: specs/cards.md, тесты 1.1–1.2. Тикеты #88acb5, #1388e0 (עבר QA 17.11.2026). Только просмотр → @prod-safe.
import { test, expect } from '../../fixtures';
import { MASK_DOTS_ONLY, HINT, openAllCards, waitMasks, expectNoFullCardNumber } from './helpers';

test.describe('כל הכרטיסים', () => {
  test('כל הכרטיסים: לא ריק, כרטיס לכל ארנק (אישי + משותפים) בלי ילדים, 4 ספרות על כל כרטיס @prod-safe #88acb5 #1388e0', async ({ asUser }) => {
    const manager = await asUser('client'); // 0500000004 — מנהל, כמה ארנקים משותפים

    // Ожидаемое число карт: личная (1) + общие кошельки пользователя (из «ארנקים משותפים — רשימה»).
    await manager.goto('/wallet/shared');
    await expect(manager.getByText('ארנקים משותפים').first()).toBeVisible({ timeout: 30_000 });
    await expect(manager.getByText(/^\d+ משתתפים$/).first()).toBeVisible({ timeout: 30_000 });
    const sharedCount = await manager.getByText(/^\d+ משתתפים$/).count();
    expect(sharedCount, 'у аккаунта 04 должны быть общие кошельки').toBeGreaterThanOrEqual(2);

    await openAllCards(manager);

    // Экран не пустой: подсказка и карточки.
    await expect(manager.getByText(HINT)).toBeVisible();
    const digits = await waitMasks(manager, 1 + sharedCount);

    // Столько карт, сколько личная + общие; на каждой ровно одна маска «•••• •••• •••• NNNN».
    expect(digits).toHaveLength(1 + sharedCount);
    for (const d of digits) expect(d).toMatch(/^\d{4}$/);
    await expect(manager.getByText(MASK_DOTS_ONLY)).toHaveCount(0);

    // Детских карт нет, полного номера нет.
    await expect(manager.getByText(/QA-ילד/)).toHaveCount(0);
    await expectNoFullCardNumber(manager);
  });

  test('כל הכרטיסים: בפתיחה פעילה הכרטיס הראשון «הכרטיס שלי», מתחתיו הנחיית הצמדה @prod-safe #88acb5 #1388e0', async ({ asUser }) => {
    const manager = await asUser('client');
    await openAllCards(manager);
    await waitMasks(manager, 1);

    const mine = manager.getByText('הכרטיס שלי', { exact: true }).first();
    await expect(mine).toBeVisible();

    // Первая карта по центру экрана (активная), остальные выглядывают сбоку.
    const box = await mine.boundingBox();
    const vp = manager.viewportSize();
    expect(box && vp).toBeTruthy();
    const centerX = box!.x + box!.width / 2;
    expect(Math.abs(centerX - vp!.width / 2)).toBeLessThan(vp!.width * 0.3);

    // Подсказка ниже карты.
    const hint = await manager.getByText(HINT).boundingBox();
    expect(hint!.y).toBeGreaterThan(box!.y);
  });
});
